+instruct mask_and_not_evex(kReg dst, kReg msrc1, kReg msrc2, immI_M1 m1) %{
+  match(Set dst (AndVMask msrc1 (XorVMask msrc2 (MaskAll m1))));
+  format %{ "mask_and_not_evex $dst, $msrc1, $msrc2\t! (~$msrc2) & $msrc1" %}
+  ins_encode %{
+    uint masklen = Matcher::vector_length(this);
+    masklen = (masklen < 16 && !VM_Version::supports_avx512dq()) ? 16 : masklen;
+    BasicType etype = T_ILLEGAL;
+    switch(masklen) {
+      case 2:
+      case 4:
+      case 8:  etype = T_BYTE; break;
+      case 16: etype = T_SHORT; break;
+      case 32: etype = T_INT; break;
+      case 64: etype = T_LONG; break;
+      default: ShouldNotReachHere(); break;
+    }
+    __ kandn(etype, $dst$$KRegister, $msrc2$$KRegister, $msrc1$$KRegister);
+  %}
+  ins_pipe( pipe_slow );
+%}
+
+instruct mask_and_not_evexL(kReg dst, kReg msrc1, kReg msrc2, immL_M1 m1) %{
+  match(Set dst (AndVMask msrc1 (XorVMask msrc2 (MaskAll m1))));
+  format %{ "mask_and_not_evex $dst, $msrc1, $msrc2\t! (~$msrc2) & $msrc1" %}
+  ins_encode %{
+    // ConL MaskAll is only used for long/double masks (max 8 lanes at 512-bit).
+    // Without AVX-512DQ, sub-16-lane k-reg ops are widened to 16 (see mask_opers_evex).
+    uint masklen = Matcher::vector_length(this);
+    masklen = (masklen < 16 && !VM_Version::supports_avx512dq()) ? 16 : masklen;
+    BasicType etype = T_ILLEGAL;
+    switch(masklen) {
+      case 2:
+      case 4:
+      case 8:  etype = T_BYTE; break;
+      case 16: etype = T_SHORT; break;
+      default: ShouldNotReachHere(); break;
+    }
+    __ kandn(etype, $dst$$KRegister, $msrc2$$KRegister, $msrc1$$KRegister);
+  %}
+  ins_pipe( pipe_slow );
+%}
+

