+
+
+    @Test
+    @IR(counts = {IRNode.X86_MASK_AND_NOT, "= 1"},
+        phase = CompilePhase.FINAL_CODE,
+        applyIfCPUFeature = {"avx512", "true"})
+    public static void testKandnAndMXorMaskAllByte() {
